import { useState } from 'react';

export default function FloatingButtons() {
    const [expanded, setExpanded] = useState(false);

    return (
        <div style={{
            position: 'fixed',
            bottom: 28,
            right: 28,
            zIndex: 9998,
            display: 'flex',
            flexDirection: 'column',
            alignItems: 'flex-end',
            gap: 12,
        }}>
            {/* Expanded buttons */}
            {expanded && (
                <div style={{ display: 'flex', flexDirection: 'column', gap: 10, animation: 'fadeInUp 0.3s ease' }}>
                    <style>{`@keyframes fadeInUp { from { opacity: 0; transform: translateY(10px); } to { opacity: 1; transform: translateY(0); } }`}</style>

                    {/* Call */}
                    <a
                        href="tel:+917049711475"
                        style={{
                            display: 'flex',
                            alignItems: 'center',
                            gap: 10,
                            background: '#333',
                            color: 'var(--zy-white)',
                            textDecoration: 'none',
                            padding: '10px 16px 10px 12px',
                            borderRadius: 28,
                            fontSize: 13,
                            fontWeight: 600,
                            fontFamily: 'var(--font-heading)',
                            boxShadow: '0 4px 20px rgba(0,0,0,0.3)',
                            transition: 'transform 0.3s ease',
                        }}
                        onMouseEnter={e => { (e.currentTarget).style.transform = 'scale(1.05)'; }}
                        onMouseLeave={e => { (e.currentTarget).style.transform = 'scale(1)'; }}
                    >
                        <div style={{
                            width: 36, height: 36, borderRadius: '50%',
                            background: '#fff', color: '#000',
                            display: 'flex', alignItems: 'center', justifyContent: 'center',
                        }}>
                            <svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2">
                                <path d="M22 16.92v3a2 2 0 01-2.18 2 19.79 19.79 0 01-8.63-3.07 19.5 19.5 0 01-6-6 19.79 19.79 0 01-3.07-8.67A2 2 0 014.11 2h3a2 2 0 012 1.72c.127.96.361 1.903.7 2.81a2 2 0 01-.45 2.11L8.09 9.91a16 16 0 006 6l1.27-1.27a2 2 0 012.11-.45c.907.339 1.85.573 2.81.7A2 2 0 0122 16.92z" />
                            </svg>
                        </div>
                        Call Us
                    </a>

                    {/* WhatsApp */}
                    <a
                        href="https://wa.me/917049711475"
                        target="_blank"
                        rel="noopener noreferrer"
                        style={{
                            display: 'flex',
                            alignItems: 'center',
                            gap: 10,
                            background: '#25D366',
                            color: 'var(--zy-white)',
                            textDecoration: 'none',
                            padding: '10px 16px 10px 12px',
                            borderRadius: 28,
                            fontSize: 13,
                            fontWeight: 600,
                            fontFamily: 'var(--font-heading)',
                            boxShadow: '0 4px 20px rgba(37,211,102,0.3)',
                            transition: 'transform 0.3s ease',
                        }}
                        onMouseEnter={e => { (e.currentTarget).style.transform = 'scale(1.05)'; }}
                        onMouseLeave={e => { (e.currentTarget).style.transform = 'scale(1)'; }}
                    >
                        <div style={{
                            width: 36, height: 36, borderRadius: '50%',
                            background: 'rgba(255,255,255,0.2)',
                            display: 'flex', alignItems: 'center', justifyContent: 'center',
                        }}>
                            <svg width="20" height="20" viewBox="0 0 24 24" fill="#fff">
                                <path d="M17.472 14.382c-.297-.149-1.758-.867-2.03-.967-.273-.099-.471-.148-.67.15-.197.297-.767.966-.94 1.164-.173.199-.347.223-.644.075-.297-.15-1.255-.463-2.39-1.475-.883-.788-1.48-1.761-1.653-2.059-.173-.297-.018-.458.13-.606.134-.133.298-.347.446-.52.149-.174.198-.298.298-.497.099-.198.05-.371-.025-.52-.075-.149-.669-1.612-.916-2.207-.242-.579-.487-.5-.669-.51-.173-.008-.371-.01-.57-.01-.198 0-.52.074-.792.372-.272.297-1.04 1.016-1.04 2.479 0 1.462 1.065 2.875 1.213 3.074.149.198 2.096 3.2 5.077 4.487.709.306 1.262.489 1.694.625.712.227 1.36.195 1.871.118.571-.085 1.758-.719 2.006-1.413.248-.694.248-1.289.173-1.413-.074-.124-.272-.198-.57-.347m-5.421 7.403h-.004a9.87 9.87 0 01-5.031-1.378l-.361-.214-3.741.982.998-3.648-.235-.374a9.86 9.86 0 01-1.51-5.26c.001-5.45 4.436-9.884 9.888-9.884 2.64 0 5.122 1.03 6.988 2.898a9.825 9.825 0 012.893 6.994c-.003 5.45-4.437 9.884-9.885 9.884m8.413-18.297A11.815 11.815 0 0012.05 0C5.495 0 .16 5.335.157 11.892c0 2.096.547 4.142 1.588 5.945L.057 24l6.305-1.654a11.882 11.882 0 005.683 1.448h.005c6.554 0 11.89-5.335 11.893-11.893a11.821 11.821 0 00-3.48-8.413z" />
                            </svg>
                        </div>
                        WhatsApp
                    </a>
                </div>
            )}

            {/* Toggle Button */}
            <button
                onClick={() => setExpanded(!expanded)}
                aria-label="Contact options"
                style={{
                    width: 56,
                    height: 56,
                    borderRadius: '50%',
                    background: expanded ? '#333' : '#25D366',
                    border: 'none',
                    display: 'flex',
                    alignItems: 'center',
                    justifyContent: 'center',
                    cursor: 'pointer',
                    boxShadow: expanded
                        ? '0 4px 20px rgba(0,0,0,0.3)'
                        : '0 4px 20px rgba(37, 211, 102, 0.3)',
                    transition: 'all 0.3s ease',
                    transform: expanded ? 'rotate(45deg)' : 'rotate(0)',
                    animation: expanded ? 'none' : 'wa-pulse 8s ease-in-out infinite',
                }}
            >
                {expanded ? (
                    <svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="#fff" strokeWidth="2.5">
                        <line x1="12" y1="5" x2="12" y2="19" /><line x1="5" y1="12" x2="19" y2="12" />
                    </svg>
                ) : (
                    <svg width="28" height="28" viewBox="0 0 24 24" fill="#fff">
                        <path d="M20 2H4c-1.1 0-2 .9-2 2v18l4-4h14c1.1 0 2-.9 2-2V4c0-1.1-.9-2-2-2zm0 14H6l-2 2V4h16v12z" />
                    </svg>
                )}
            </button>
        </div>
    );
}
